(7085554, 1079102, 30861, '<td valign="top">New Mexico?</td>', 'New Mexico?', '2013-08-12 01:22:15.000000', NULL, 1),
(7085557, 1079067, 141247, '<td valign="top">wow!</td>', 'wow!', '2013-08-12 01:24:01.000000', NULL, 1),
(7085560, 1078951, 141247, '<td valign="top">super!</td>', 'super!', '2013-08-12 01:28:09.000000', NULL, 1),
(7085561, 1079044, 96751, '<td valign="top">I hope this does well for you, Alessandro. It''s a fascinating portrait.</td>', 'I hope this does well for you, Alessandro. It''s a fascinating portrait.', '2013-08-12 01:30:10.000000', NULL, 1),
(7085562, 1078356, 96751, '<td valign="top">Not your classic bokeh, but what an interesting composition. Almost 3-d</td>', 'Not your classic bokeh, but what an interesting composition. Almost 3-d', '2013-08-12 01:30:32.000000', NULL, 1),
(7085563, 1078878, 96751, '<td valign="top">Terrific! I''ve only just started, but this has the hallmarks of past winners. Creative bokeh, for sure. And so pretty</td>', 'Terrific! I''ve only just started, but this has the hallmarks of past winners. Creative bokeh, for sure. And so pretty', '2013-08-12 01:31:08.000000', NULL, 1),
(7085564, 1079074, 96751, '<td valign="top">That''s a LOT of fluff!  I love the portrait, not feeling this is a good example of bokeh, even though it is there.</td>', 'That''s a LOT of fluff!  I love the portrait, not feeling this is a good example of bokeh, even though it is there.', '2013-08-12 01:32:19.000000', NULL, 1),
(7085566, 1079075, 96751, '<td valign="top">A melting song</td>', 'A melting song', '2013-08-12 01:32:30.000000', NULL, 1),
(7085567, 1079005, 96751, '<td valign="top">How utterly charming. Like fairy intimates hanging on a clothesline</td>', 'How utterly charming. Like fairy intimates hanging on a clothesline', '2013-08-12 01:33:02.000000', NULL, 1),
(7085568, 1079102, 96751, '<td valign="top">Wonderful light. An interesting choice for bokeh. I don''t think most <strike>male </strike>viewers will get past the lady :-)</td>', 'Wonderful light. An interesting choice for bokeh. I don''t think most male viewers will get past the lady :-)', '2013-08-12 01:33:46.000000', NULL, 1),
(7085569, 1078842, 96751, '<td valign="top">What a capture.</td>', 'What a capture.', '2013-08-12 01:33:57.000000', NULL, 1),
(7085571, 1079058, 96751, '<td valign="top">A ballerina''s tutu!!</td>', 'A ballerina''s tutu!!', '2013-08-12 01:34:17.000000', NULL, 1),
(7085574, 1079110, 96751, '<td valign="top">Very pretty colors, but I feel the bokeh really overpowers the subject, which is a bit blown</td>', 'Very pretty colors, but I feel the bokeh really overpowers the subject, which is a bit blown', '2013-08-12 01:34:51.000000', NULL, 1),
(7085577, 1079107, 96751, '<td valign="top">A very evocative image. Marvelous lines and colors. Interesting take on the challenge.</td>', 'A very evocative image. Marvelous lines and colors. Interesting take on the challenge.', '2013-08-12 01:35:54.000000', NULL, 1),
(7085579, 1078997, 96751, '<td valign="top">This must be the best-dressed butterfly EVER. Delightful</td>', 'This must be the best-dressed butterfly EVER. Delightful', '2013-08-12 01:37:46.000000', NULL, 1),
(7085580, 1079072, 96751, '<td valign="top">I don''t know where to look first!!!The bokeh is quite overwhelming, but then the lovely purple colors draw me to the flowers, and then I discover the little mantis checking me out. I think too many things are fighting for my attention, although individually, each element is fantastic.</td>', 'I don''t know where to look first!!!The bokeh is quite overwhelming, but then the lovely purple colors draw me to the flowers, and then I discover the little mantis checking me out. I think too many things are fighting for my attention, although individually, each element is fantastic.', '2013-08-12 01:39:19.000000', NULL, 1),
(7085584, 1079066, 96751, '<td valign="top">LOL at the title. Adorable energy</td>', 'LOL at the title. Adorable energy', '2013-08-12 01:40:28.000000', NULL, 1),
(7085586, 1078950, 96751, '<td valign="top">Who''s her stylist! Fabulous portrait</td>', 'Who''s her stylist! Fabulous portrait', '2013-08-12 01:41:34.000000', NULL, 1),
(7085589, 1078370, 96751, '<td valign="top">I love it when they''re all fluffed up like that, but that big orange blog on the right to draw most of my attention.</td>', 'I love it when they''re all fluffed up like that, but that big orange blog on the right to draw most of my attention.', '2013-08-12 01:42:14.000000', NULL, 1),
