(7089419, 1079050, 108580, '<td valign="top">Loved this one. 8! (<strike>Sot</strike> <u>Shot</u> details would be nice!) WD.<br/><br/><i>Message edited by author 2013-08-20 15:01:39.</i></td>', 'Loved this one. 8! (Sot Shot details would be nice!) WD.', '2013-08-19 02:16:37.000000', '2013-08-20 16:01:39.000000', 0),
