(7090035, 1078951, 23098, '<td valign="top">Congrats on the blue.  Great capture of the dragonfly in its bokeh-magic environs.</td>', 'Congrats on the blue.  Great capture of the dragonfly in its bokeh-magic environs.', '2013-08-20 09:13:00.000000', NULL, 0),
