(7090042, 1079005, 23098, '<td valign="top">Beautiful image, congrats on the top ten finish.</td>', 'Beautiful image, congrats on the top ten finish.', '2013-08-20 10:09:50.000000', NULL, 0),
(7090471, 1078951, 30861, '<td valign="top">Graham, this is absolutely splendid. I think it''s my favorite of all DPC dragonfly shots. The ephemeral quality of the bokeh is to die for. I knew it would take the blue! Congrats!</td>', 'Graham, this is absolutely splendid. I think it''s my favorite of all DPC dragonfly shots. The ephemeral quality of the bokeh is to die for. I knew it would take the blue! Congrats!', '2013-08-20 22:53:17.000000', NULL, 0),
(7090472, 1079017, 30861, '<td valign="top">So serene, so Irene! Congrats!</td>', 'So serene, so Irene! Congrats!', '2013-08-20 22:53:45.000000', NULL, 0),
(7090474, 1079050, 30861, '<td valign="top">May be the nicest wing rendition I''ve ever seen on a hummer, soft-ye-sharp, frozen-yet-dynamic. Congrats!</td>', 'May be the nicest wing rendition I''ve ever seen on a hummer, soft-ye-sharp, frozen-yet-dynamic. Congrats!', '2013-08-20 22:54:33.000000', NULL, 0),
