(7090477, 1079005, 30861, '<td valign="top">Understated, serenely elegant, and somehow inhabiting the fringe of the erotic. Great job!</td>', 'Understated, serenely elegant, and somehow inhabiting the fringe of the erotic. Great job!', '2013-08-20 22:56:07.000000', NULL, 0),
(7090694, 1078951, 97225, '<td valign="top">Congratulations on the blue, Mary Ann. It''s a gorgeous shot. I''m glad you were rewarded for your efforts, makes some ant bites tolerable.</td>', 'Congratulations on the blue, Mary Ann. It''s a gorgeous shot. I''m glad you were rewarded for your efforts, makes some ant bites tolerable.', '2013-08-21 03:04:02.000000', NULL, 0),
